{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/patterns/action-group.json
    One or two calls to action side by side: a filled primary button and an outline secondary one. Links, not handlers: the page decides what they open.
    Props (p): primary, primaryHref, secondary, secondaryHref, align. -#}
{%- set v_primary = og_def(p['primary'], none) -%}
{%- set v_primaryHref = og_def(p['primaryHref'], none) -%}
{%- set v_secondary = og_def(p['secondary'], none) -%}
{%- set v_secondaryHref = og_def(p['secondaryHref'], none) -%}
{%- set v_align = og_def(p['align'], 'start') -%}
{%- set c_3 -%}
  {%- set c_1 -%}
    {{ og_text(v_primary) }}
  {%- endset -%}
  {{ og_include('compose/button.html.j2', {'p': {'Variant': 'default', 'Size': 'default', 'Href': og_url(og_s(v_primaryHref)), 'Attrs': og_attrs(['data-testid', 'action-primary'])}, 'children': c_1}) }}
  {%- if og_t(v_secondary) %}
    {%- set c_2 -%}
      {{ og_text(v_secondary) }}
    {%- endset -%}
    {{ og_include('compose/button.html.j2', {'p': {'Variant': 'outline', 'Size': 'default', 'Href': og_url(og_s(v_secondaryHref)), 'Attrs': og_attrs(['data-testid', 'action-secondary'])}, 'children': c_2}) }}
  {%- endif %}
{%- endset -%}
{{ og_include('compose/group.html.j2', {'p': {'Gap': '4', 'Align': 'center', 'Justify': og_s(('center' if og_t(og_eq(v_align, 'center')) else 'start')), 'Class': 'flex-wrap', 'Attrs': og_attrs(['data-slot', 'action-group'])}, 'children': c_3}) }}
